def clean_email(self):
        email = self.cleaned_data["email"].lower()
        if User.objects.filter(email__iexact=email).exists():
            raise ValidationError("An account already exists for this email address.")

def clean_file(self):
        uploaded = self.cleaned_data["file"]
        suffix = Path(uploaded.name).suffix.lower()
        if suffix not in settings.PORTAL_ALLOWED_UPLOAD_EXTENSIONS:
            raise ValidationError("Allowed file types are PDF, TXT, PNG, JPG, and JPEG.")
        if uploaded.size > settings.PORTAL_MAX_UPLOAD_SIZE:
            raise ValidationError("Files must be 5 MB or smaller.")
        return uploaded

